// Fields the app sends with payments so they can be recorded offline and
// synced later. Pure: used by the API routes and tested.

const CLIENT_ID = /^[A-Za-z0-9-]{8,64}$/;
/** A queued payment older than this is refused rather than silently backdated. */
export const MAX_OFFLINE_AGE_MS = 30 * 24 * 60 * 60 * 1000;
/** Allow for a phone clock that runs a little fast. */
const MAX_CLOCK_SKEW_MS = 10 * 60 * 1000;

export type ParsedField<T> = { ok: true; value: T | null } | { ok: false; error: string };

/** Optional idempotency key generated by the app (a UUID). */
export function parseClientId(value: unknown): ParsedField<string> {
  if (value === undefined || value === null || value === "") return { ok: true, value: null };
  if (typeof value !== "string" || !CLIENT_ID.test(value)) return { ok: false, error: "Invalid client_id" };
  return { ok: true, value };
}

/** Optional time the payment was actually taken (set when it was recorded offline). */
export function parseRecordedAt(value: unknown, now = new Date()): ParsedField<Date> {
  if (value === undefined || value === null || value === "") return { ok: true, value: null };
  const date = typeof value === "string" ? new Date(value) : null;
  if (!date || Number.isNaN(date.getTime())) return { ok: false, error: "Invalid recorded_at" };
  if (date.getTime() > now.getTime() + MAX_CLOCK_SKEW_MS) {
    return { ok: false, error: "recorded_at is in the future; check the device's date and time" };
  }
  if (now.getTime() - date.getTime() > MAX_OFFLINE_AGE_MS) {
    return { ok: false, error: "This payment was recorded more than 30 days ago; enter it again with the right date" };
  }
  return { ok: true, value: date };
}
